(function(root){
  'use strict';
  const categories=['Food','Transport','Data','Savings','Emergency','Flexible','Academics'];
  const MAX=100000000000; // kobo, per entry
  function amount(value){if(!Number.isSafeInteger(value)||value<0||value>MAX)throw Error('Use a valid non-negative amount within the supported limit.');return value;}
  function parse(value){const text=String(value).trim();if(!/^\d+(\.\d{1,2})?$/.test(text))throw Error('Enter an amount with at most two decimal places.');const [whole,decimal='']=text.split('.');return amount(Number(whole)*100+Number(decimal.padEnd(2,'0')));}
  function positive(value){amount(value);if(value===0)throw Error('Amount must be greater than zero.');return value;}
  const total=values=>values.reduce((sum,n)=>{const next=sum+n;if(!Number.isSafeInteger(next))throw Error('Total exceeds the supported range.');return next;},0);
  const clone=s=>JSON.parse(JSON.stringify(s));
  function date(value){if(!/^\d{4}-\d{2}-\d{2}$/.test(value)||!Number.isFinite(Date.parse(value+'T00:00:00Z'))||new Date(value+'T00:00:00Z').toISOString().slice(0,10)!==value)throw Error('Choose a valid date.');return value;}
  function text(value,label){if(typeof value!=='string'||!value.trim()||value.length>100)throw Error('Enter '+label+' (up to 100 characters).');return value.trim();}
  const today=()=>new Date().toISOString().slice(0,10);
  function create(){return {version:1,rules:categories.map((category,i)=>({category,target:[30000,15000,10000,20000,10000,15000,0][i]*100,essential:['Food','Data','Emergency'].includes(category)})),expected:10000000,events:[],failures:[],subscriptions:[],partner:{name:'',relationship:'',shareTotals:false,shareCategories:false,shareMilestones:false,shareAlerts:false,limit:8000000},card:{provider:'simulation',category:'Food',status:'active',limit:1000000},notices:[]};}
  function ledger(s){const allocated=Object.fromEntries(categories.map(c=>[c,0])),spent={...allocated};let income=0;const references=new Set();for(const event of s.events){if(references.has(event.ref))throw Error('Duplicate transaction reference in saved data.');references.add(event.ref);positive(event.amount);if(event.kind==='income'){income=total([income,event.amount]);for(const c of categories)allocated[c]=total([allocated[c],amount(event.allocations[c]||0)]);}else if(event.kind==='expense')spent[event.category]=total([spent[event.category]||0,event.amount]);else throw Error('Unknown transaction type.');}const balances=Object.fromEntries(categories.map(c=>[c,allocated[c]-spent[c]]));if(Object.values(balances).some(n=>n<0)||total(Object.values(allocated))>income)throw Error('Saved records contain inconsistent balances.');return {income,allocated,spent,balances,totalSpent:total(Object.values(spent)),remaining:income-total(Object.values(spent)),unallocated:income-total(Object.values(allocated)),reserved:balances.Savings+balances.Emergency};}
  function rules(s,rules,expected){positive(expected);if(!Array.isArray(rules)||rules.length!==categories.length||new Set(rules.map(r=>r.category)).size!==categories.length||rules.some(r=>!categories.includes(r.category)))throw Error('Provide one rule for every category.');rules.forEach(r=>amount(r.target));if(total(rules.map(r=>r.target))>expected)throw Error('Rules exceed your expected income. Reduce an allocation.');const next=clone(s);next.rules=rules.map(r=>({...r,essential:!!r.essential}));next.expected=expected;return next;}
  // Priority tiers receive funds first. Integer largest-remainder apportionment
  // keeps every kobo accounted for when a tier cannot be funded in full.
  function distribute(available,rules){positive(available);const result=Object.fromEntries(categories.map(c=>[c,0]));let left=available;for(const essential of [true,false]){const tier=rules.filter(r=>!!r.essential===essential&&r.target>0),target=total(tier.map(r=>r.target)),pool=Math.min(left,target);if(!target||!pool)continue;const rows=tier.map((r,i)=>{const product=BigInt(pool)*BigInt(r.target),den=BigInt(target);return {category:r.category,n:Number(product/den),rem:product%den,i};});let remainder=pool-total(rows.map(r=>r.n));rows.sort((a,b)=>a.rem===b.rem?a.i-b.i:a.rem>b.rem?-1:1);for(const row of rows){if(remainder>0){row.n++;remainder--;}result[row.category]=row.n;}left-=pool;}return result;}
  function receive(s,input){const ref=text(input.ref,'a unique payment reference'),previous=s.events.find(e=>e.ref===ref);if(previous){if(previous.kind!=='income'||previous.amount!==input.amount)throw Error('This reference is already used for another transaction.');return {state:s,duplicate:true};}positive(input.amount);const allocations=distribute(input.amount,s.rules),next=clone(s);next.events.push({kind:'income',ref,amount:input.amount,date:date(input.date||today()),note:text(input.note||'Simulated allowance','an income description'),allocations,ruleSnapshot:clone(s.rules)});ledger(next);return {state:next,duplicate:false};}
  function spend(s,input){const ref=text(input.ref,'a transaction reference'),previous=s.events.find(e=>e.ref===ref);if(previous){if(previous.kind!=='expense'||previous.amount!==input.amount||previous.category!==input.category||previous.subscriptionId!==(input.subscriptionId||null)||previous.card!==(input.card||false))throw Error('Reference already used for a different transaction.');return {state:s,duplicate:true};}positive(input.amount);if(!categories.includes(input.category)||input.category==='Savings')throw Error('Select a spending category. Savings are protected.');if(ledger(s).balances[input.category]<input.amount)throw Error('Insufficient '+input.category+' funds. Review your plan or simulate another income.');const next=clone(s);next.events.push({kind:'expense',ref,amount:input.amount,category:input.category,date:date(input.date||today()),note:text(input.note,'a description'),subscriptionId:input.subscriptionId||null,card:input.card||false});ledger(next);return {state:next,duplicate:false};}
  function subscription(s,input){const next=clone(s);const sub={id:text(input.id,'a subscription ID'),name:text(input.name,'a subscription name'),network:text(input.network,'a preferred network'),plan:text(input.plan,'a plan'),amount:positive(input.amount),limit:positive(input.limit),category:input.category,condition:input.condition,due:date(input.due)};if(!categories.includes(sub.category)||sub.category==='Savings')throw Error('Choose a spending category.');if(!['date','depleted'].includes(sub.condition))throw Error('Select a renewal condition.');if(sub.amount>sub.limit)throw Error('The renewal amount exceeds its monthly spending limit.');const i=next.subscriptions.findIndex(x=>x.id===sub.id);if(i<0)next.subscriptions.push(sub);else next.subscriptions[i]=sub;return next;}
  function nextMonth(value){const d=new Date(value+'T12:00:00Z'),day=d.getUTCDate();d.setUTCDate(1);d.setUTCMonth(d.getUTCMonth()+1);const last=new Date(Date.UTC(d.getUTCFullYear(),d.getUTCMonth()+1,0)).getUTCDate();d.setUTCDate(Math.min(day,last));return d.toISOString().slice(0,10);}
  function renew(s,input){const sub=s.subscriptions.find(x=>x.id===input.id);if(!sub)throw Error('Subscription not found.');const ref=text(input.ref,'a renewal reference'),previous=s.events.find(e=>e.ref===ref);if(previous){if(previous.subscriptionId!==sub.id)throw Error('Reference already used.');return {state:s,duplicate:true};}const when=date(input.date||today());if(sub.condition==='date'&&when<sub.due)throw Error('This subscription is not due yet.');if(sub.condition==='depleted'&&!input.depleted)throw Error('Confirm that data has finished to simulate this renewal.');const used=total(s.events.filter(e=>e.subscriptionId===sub.id&&e.date.slice(0,7)===when.slice(0,7)).map(e=>e.amount));if(used+sub.amount>sub.limit)throw Error('Monthly subscription spending limit reached. Review its settings.');const result=spend(s,{ref,amount:sub.amount,category:sub.category,note:'Simulated renewal: '+sub.name,date:when,subscriptionId:sub.id});const target=result.state.subscriptions.find(x=>x.id===sub.id);target.due=nextMonth(when);return result;}
  function failure(s,input,error){const next=clone(s);if(!next.failures.some(f=>f.ref===input.ref))next.failures.push({ref:input.ref||'unreferenced',message:String(error.message),date:today()});return next;}
  function partnerView(s){const p=s.partner,l=ledger(s);return {name:p.name,relationship:p.relationship,status:p.name?'Simulated partner — no invitation sent':'Not configured',...(p.shareTotals?{totals:{income:l.income,spent:l.totalSpent,remaining:l.remaining}}:{}),...(p.shareCategories?{categories:l.balances}:{}),...(p.shareMilestones?{milestones:['Savings reserved: '+l.balances.Savings+' kobo',...s.events.filter(e=>e.kind==='income').map(e=>'Allowance allocated: '+e.ref)]}:{}),...(p.shareAlerts?{alerts:l.totalSpent>=p.limit?['Agreed spending alert threshold reached.']:['No spending limit alert.']}:{} )};}
  function validate(s){if(s?.version!==1||!Array.isArray(s.events)||!Array.isArray(s.rules)||!Array.isArray(s.subscriptions)||!Array.isArray(s.failures)||!s.partner||!s.card)throw Error('Saved smart-plan data could not be read.');rules(s,s.rules,s.expected);for(const event of s.events){text(event.ref,'a transaction reference');date(event.date);if(event.kind==='income'){if(!event.allocations||Object.keys(event.allocations).some(c=>!categories.includes(c))||total(Object.values(event.allocations).map(amount))>event.amount)throw Error('Saved income allocations are inconsistent.');}else if(!categories.includes(event.category)||event.category==='Savings')throw Error('Saved expense category is invalid.');}ledger(s);if(!categories.includes(s.card.category)||s.card.category==='Savings'||!['active','frozen'].includes(s.card.status))throw Error('Saved card settings are invalid.');positive(s.card.limit);return s;}
  const api={categories,parse,amount,positive,total,date,create,ledger,rules,distribute,receive,spend,subscription,renew,failure,partnerView,validate,nextMonth};if(typeof module!=='undefined')module.exports=api;root.Allocation=api;
})(typeof window==='undefined'?globalThis:window);
